def protocol_handlers(cls, protocol_version=None):
    if protocol_version is None or not isinstance(protocol_version, tuple):
        raise TypeError('protocol_version must be a tuple')
    handlers = {}
    for version in supported_versions:
        handler_class = cls.get_handler(version)
        if handler_class:
            handlers[version] = handler_class
    if protocol_version is not None:
        handlers = {version: handler_class for version, handler_class in handlers.items() if handler_class is not None}
    return handlers

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx):
            try:
                result = func(tx)
                if timeout is not None:
                    tx.commit()
                else:
                    tx.commit_if_newly_created()
                return result
            except Exception as e:
                if timeout is not None:
                    tx.rollback()
                else:
                    tx.rollback_if_newly_created()
                raise e
        return wrapper
    return decorator

def index(self, key):
