    return self.data.index(key)

def data(self, *keys):
    if not keys:
        return {k: None for k in self._fields}
    values = [None] * len(self._fields)
    for index, key in enumerate(keys):
        if isinstance(key, int) and key < len(self._fields):
            values[index] = self._fields[index][1]
        elif isinstance(key, str) and key in self._fields:
            values[key] = self._fields[key][1]
        else:
            raise KeyError(f"Key {key!r} not found in record")
    return dict(zip(self._fields, values))

