def ttl_cache(maxsize: int = 128, ttl: int = 600, timer: Callable[[Any], float] = time.monotonic, typed: bool = False) -> Callable:
    cache = {}
    timestamps = {}

    def memoize(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key in cache:
            if cached_time >= timer(key) + ttl:
                del cache[key]
                del timestamps[key]
            else:
                return cache[key]

        result = callable(*args, **kwargs)
        try:
            timestamps[key] = timer(key)
            if len(cache) >= maxsize:
                oldest_key = min(timestamps, key=timestamps.get)
                del cache[oldest_key]
                del timestamps[oldest_key]
            cache[key] = result
        except Exception as e:
            del cache[key]
            del timestamps[key]
            raise e

        return result

    return memoize

def mru_cache(maxsize=128, typed=False):
    def wrapper(f):
        cache = OrderedDict()
        def memoized(*args):
            # Check if the argument is of the correct type (only if typed is True)
            if typed and not all(isinstance(arg, type(e)) for arg, e in zip(args, cache.values())):
                raise TypeError("All arguments must be of the same type.")
            # If the argument is not in the cache, add it and remove the oldest entry if the cache is full
            if args in cache:
                cache.pop(args)
            cache[args] = f(*args)
            return cache[args]
        return memoized
    return wrapper

def lru_cache(maxsize=128, typed=False):
    def memoize_wrapper(func):
        cache = {}
        def wrapper(*args):
            if args not in cache:
                cache[args] = func(*args)
            return cache[args]
        return wrapper
    return memoize_wrapper

