def minimalBases(classes):
    if not isinstance(classes, list):
        raise ValueError("The input must be a list of base classes.")

    if not all(isinstance(cls, str) for cls in classes):
        raise ValueError("All base classes must be provided as strings.")

    minimal_class = classes
    for i in range(len(classes) - 1):
        for j in range(i + 1, len(classes)):
            if classes[j] < minimal_class[-1]:
                minimal_class = [classes[i]] + minimal_class

    return minimal_class

