def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    # Chech if the input function is None or not callable
    if not namefunc or not callable(namefunc):
        raise ValueError('namefunc must be callable')

    def _inner_tzname(*args, **kwargs):
        try:
            # Call the namefunc with arguments and convert results to bytes in Python 2
            result = namefunc(*args, **kwargs).encode('latin-1')
            return result
        except UnicodeEncodeError as e:
            # Handle UnicodeEncodeError by raising a different exception
            raise ValueError(f'Conversion to byte string failed: {e}')
        except Exception as e:
            # Handle any other unexpected exceptions
            raise ValueError(f'An error occurred: {e}')

    return _inner_tzname

