        raise ValueError("Version must be a string")
    if len(version) == 0:
        return "0.1"

    if version[0] != '0':
        split_version = map(int, version.split('.'))
        split_version[-1] += 1
        return '.'.join(map(str, split_version))

    split_version = map(int, '0.' + version.split('.')[1].lstrip('0')).split('.')
