def validate_version_inventories(self, version_dirs):
    storage = self.inventories_by_target_values
    inventory_hash_map = {}
    differing_content_digests = {}
    content_digests = {}

    if not version_dirs:
        raise ValueError("The list of version directories cannot be empty.")

    # Process the inventory for each version
    for version in version_dirs:
        inventory_path = f"{version}/inventory.json"
        if inventory_path in storage:
            version_inventory = self.load_inventory(inventory_path)

            # Get the content digest for the root inventory
            root_inventory_id = "root"
            if root_inventory_id in self.inventories_by_target_values:
                content_digest = self.content_digests[self.inventories_by_target_values[root_inventory_id].digest]
            else:
                content_digest = "-"

            # Compare content digests for each version
            for target_value in version_inventory["targets"]:
                target_value_hash = hashlib.sha256(self.json.dumps(target_value).encode()).hexdigest()
                if target_value_hash != content_digest:
                    differing_content_digests[target_value_hash] = target_value
                    content_digests[target_value_hash] = target_value

            # Store the inventory hash
            inventory_hash_map[version] = hashlib.sha256(self.json.dumps(deepcopy(version_inventory)).encode()).hexdigest()

    return inventory_hash_map, differing_content_digests

