def deep_merge_nodes(nodes):
    merged_data = {}

    for key, value in nodes:
        if key in merged_data:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(merged_data[key], ruamel.yaml.nodes.MappingNode):
                merged_data[key] = deep_merge_nodes([(k, v) for k, v in merged_data[key].items() if k in value] + [(k, v) for k, v in value.items() if k not in merged_data[key]])
