def split(s, platform='this'):
    if platform != 'this':
        raise ValueError("platform must be one of 'this', 1, 0')

    if platform == '1':
        pattern = re.compile(r'(\S+)')
    elif platform == '0':
        pattern = re.compile(r'(?:(?:[A-Za-z0-9]|\\(?!["\\]))+)')
    else:
        if platform == 'this':
            platform = platform.upper()
        pattern = re.compile(r'(?:(?:[A-Za-z0-9]|/\\(?!["\\]))+)')

    return re.findall(pattern, s)

