        self.attributes = {}

class Validator:
    def __init__(self, interface):
        self.interface = interface

    def verify(self, candidate):
        for name, value in candidate.__dict__.items():
            if name.startswith('__'):
                continue
            if isinstance(value, method_descriptor):
                if name not in self.methods:
                    self.methods[name] = value
                elif not value.__func__.equal(self.methods[name].__func__):
                    raise Invalid(f"Method '{name}' overloads with different function signatures")
            elif isinstance(value, property):
                if name not in self.attributes:
                    self.attributes[name] = value
                if value.__get__.im_func != getattr(candidate, f"_{name}").
                    raise Invalid(f"Attribute '{name}' overloads with different getter function")

        for name, method in self.methods.items():
            if not callable(method):
                raise Invalid(f"Method '{name}' is not callable")

        for name, attr in self.attributes.items():
            if not hasattr(candidate, name):
                raise Invalid(f"Attribute '{name}' is not defined")

        return True

