def determineMetaclass(bases, explicit_mc=None):
    if not bases:
        raise ValueError("bases cannot be empty")

    if explicit_mc:
        return explicit_mc

    metaclass = None
    for base in bases:
        if hasattr(base, '__metaclass__'):
            metaclass = base.__metaclass__
            break

    if not metaclass:
        raise ValueError("Cannot find metaclass in bases or explicitly from __metaclass__")

    return metaclass

def pop(self, key, default=None):
    if key in self._data:
        value = self._data[key]
        del self._data[key]
        return value
    else:
        if default is not None:
            return default
        else:
            raise KeyError(f"Key not found: {key}")

