def parse_diaspora_webfinger(document: str) -> Dict:
    if not isinstance(document, str):
        raise TypeError("Document must be a string")

    # A refactored function to parse the webfinger content and validate it
    def parse_content(content):
        if content.startswith("json:"):
            try:
                data = json.loads(content[6:])
                return data
            except json.JSONDecodeError as e:
                raise ValueError("Invalid JSON content")

        elif content.startswith("xrd:"):
            try:
                data = json.loads(content[6:])
                return data
            except json.JSONDecodeError as e:
                raise ValueError("Invalid JSON content")

        elif content.startswith("<http://"):
            raise ValueError("Unsupported content type")

        else:
            raise ValueError("Unknown content type")

    try:
        parsed_data = parse_content(document)
        if "xrd" in parsed_data:
            return parsed_data["xrd"]
        else:
            raise ValueError("No XRD document found")

    except ValueError as e:
        print(f"Error parsing webfinger: {e}")
        raise

