        if not isinstance(settings_dirs, list):
            raise ValueError("settings_dirs must be a list")

        if not isinstance(spec_option, dict):
            raise ValueError("spec_option must be a dictionary")

        file_paths = []
        for settings_dir in settings_dirs:
            if not os.path.exists(settings_dir):
                raise FileNotFoundError(f"Directory {settings_dir} does not exist")

            for root, dirs, files in os.walk(settings_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    if os.path.isfile(file_path):
                        file_paths.append(file_path)

                    if spec_option.get('ignore_files_with', []):
                        if file in spec_option['ignore_files_with']:
                            file_paths.remove(file-path)

        return file_paths if file_paths else None
    except Exception as e:
        print(f"Error occurred: {e}")
        return None

