def get_plugin_spec_flatten_dict(plugin_dir):
    flatten_dict = {}
    try:
        # Walk through the directory to find all plugin files
        for root, dirs, files in os.walk(plugin_dir):
            for file in files:
                # Assuming each file contains properties of the plugin
                config_file_path = os.path.join(root, file)
                with open(config_file_path, 'r') as file:
                    plugin_properties = file.read()
                    # Assuming each property key is of the form 'key=value'
                    lines = plugin_properties.split('\n')
                    for line in lines:
                        if line:
                            key, value = line.split('=')
                            flatten_dict[key.strip()] = value.strip()

    except FileNotFoundError:
        print(f"Plugin directory not found: {plugin_dir}")
        return {}

    except Exception as e:
        print(f"Error in processing plugin directory: {plugin_dir}")
        print(f"Error details: {e}")
        return {}

    return flatten_dict

